--
-- Name: _cancel_booking_core(text, text, integer, integer, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._cancel_booking_core(p_booking text, p_reason text, p_rent_refund integer, p_dep_refund integer, p_mode text, p_note text, p_approval uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare b bookings; paid_total int; dep_total int; ret_rent int; ret_dep int;
  rr int := greatest(0, coalesce(p_rent_refund,0)); dr int := greatest(0, coalesce(p_dep_refund,0));
  md text := coalesce(nullif(trim(coalesce(p_mode,'')),''),'Cash'); why text := nullif(trim(coalesce(p_reason,'')),'');
  note text := nullif(trim(coalesce(p_note,'')),'');
begin
  if not is_owner() then raise exception 'FORBIDDEN'; end if;
  if why is null then raise exception 'REASON_REQUIRED'; end if;
  select * into b from bookings where id = p_booking for update;
  if not found then raise exception 'NOT_FOUND'; end if;
  if b.status not in ('pending','confirmed') then raise exception 'BAD_STATUS'; end if;
  select coalesce(sum(amount) filter (where kind in ('rent','charge')),0) - coalesce(sum(amount) filter (where kind = 'rent_refund'),0),
         coalesce(sum(amount) filter (where kind = 'deposit'),0) - coalesce(sum(amount) filter (where kind in ('deposit_refund','charge')),0)
    into paid_total, dep_total from payments where booking_id = p_booking;
  paid_total := greatest(0, paid_total); dep_total := greatest(0, dep_total);
  if rr > paid_total or dr > dep_total then raise exception 'BAD_AMOUNT'; end if;
  ret_rent := paid_total - rr; ret_dep := dep_total - dr;

  update bookings set status = 'cancelled',
    log = log || jsonb_build_array(jsonb_build_object('t', now(),
      'm', 'Cancelled: ' || why || '. Refunded: rent Rs ' || rr || ', deposit Rs ' || dr
           || '. Kept under cancellation policy: rent Rs ' || ret_rent || ', deposit Rs ' || ret_dep
           || coalesce('. Owner note: ' || note, ''),
      'by', staff_name()))
  where id = p_booking;

  if rr > 0 then
    insert into payments(booking_id, amount, kind, purpose, mode, remarks, approval_id)
      values (p_booking, rr, 'rent_refund', 'advance_refund', md, 'Cancellation refund (owner decision)', p_approval);
  end if;
  if dr > 0 then
    insert into payments(booking_id, amount, kind, purpose, mode, remarks, approval_id)
      values (p_booking, dr, 'deposit_refund', 'deposit_refund', md, 'Cancellation deposit refund (owner decision)', p_approval);
  end if;
  -- A deposit that is kept is recorded as income (same way a deposit applied to dues at return is), so it does not
  -- linger as "deposit held" or "refund pending" on a cancelled booking.
  if ret_dep > 0 then
    insert into payments(booking_id, amount, kind, purpose, mode, remarks, approval_id)
      values (p_booking, ret_dep, 'charge', 'deposit_applied', 'From Security Deposit', 'Cancellation: deposit kept under policy', p_approval);
  end if;
  return jsonb_build_object('rent_refund', rr, 'deposit_refund', dr, 'kept_rent', ret_rent, 'kept_deposit', ret_dep);
end $$;

--
-- Name: _return_calc(text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._return_calc(p_booking text, p_lf integer, p_dc integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare b bookings; d dresses; g int := 0; today date := (now() at time zone 'Asia/Kolkata')::date; paid int; dep_held int;
  lf int := greatest(0, coalesce(p_lf, 0)); dc int := greatest(0, coalesce(p_dc, 0)); late int := 0; suggested int := 0; due int; refund int; kept int; lft int;
  cust int; u_rent int; u_cust int; u_prev int; applied jsonb := '[]'::jsonb; t int; x record;
begin
  select * into b from bookings where id = p_booking; if not found then raise exception 'NOT_FOUND'; end if;
  select * into d from dresses where id = b.dress_id;
  select coalesce(late_grace_days, 0) into g from settings limit 1;
  if b.end_date < today then late := greatest(0, (today - b.end_date) - g); end if;
  suggested := late * coalesce(d.extra_day_fee, 0);
  select coalesce(sum(amount) filter (where kind in ('rent', 'charge')), 0) - coalesce(sum(amount) filter (where kind = 'rent_refund'), 0),
         coalesce(sum(amount) filter (where kind = 'deposit'), 0) - coalesce(sum(amount) filter (where kind in ('deposit_refund', 'charge')), 0)
    into paid, dep_held from payments where booking_id = p_booking;
  due := greatest(0, b.rent + b.charges + lf + dc - paid);
  refund := greatest(0, dep_held - due);
  kept := greatest(0, least(dep_held - refund, due));
  cust := coalesce(b.custom_charge, 0); u_rent := greatest(0, b.rent - paid); u_cust := greatest(0, cust - greatest(0, paid - b.rent));
  u_prev := greatest(0, greatest(0, b.rent + b.charges - paid) - u_rent - u_cust);
  lft := kept;
  for x in select * from (values (1, u_rent, 'Unpaid rent'), (2, u_cust, 'Unpaid customization charge'), (3, u_prev, 'Earlier late fee / charges'), (4, lf, 'Late-return fee'), (5, dc, 'Damage / repair / cleaning charge')) v(o, amt, why) order by o loop
    t := least(lft, x.amt); if t > 0 then applied := applied || jsonb_build_array(jsonb_build_object('amt', t, 'why', x.why)); lft := lft - t; end if;
  end loop;
  if lft > 0 then applied := applied || jsonb_build_array(jsonb_build_object('amt', lft, 'why', 'Unpaid dues')); end if;
  return jsonb_build_object('late_days', late, 'grace_days', g, 'per_day', coalesce(d.extra_day_fee, 0), 'suggested_late_fee', suggested, 'deposit_held', dep_held,
    'owing', greatest(0, b.rent + b.charges - paid), 'refund', refund, 'kept', kept, 'applied', applied);
end $$;

--
-- Name: add_customer(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_customer(p_name text, p_phone text, p_email text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare c uuid;
begin
  if not is_owner() then raise exception 'FORBIDDEN'; end if;
  if length(trim(coalesce(p_name, ''))) = 0 then raise exception 'NAME_REQUIRED'; end if;
  if not phone_valid(p_phone) then raise exception 'BAD_PHONE'; end if;
  insert into customers (name, phone_key, email) values (trim(p_name), phone_key(p_phone), nullif(trim(coalesce(p_email, '')), ''))
    on conflict (phone_key, lower(trim(name))) do nothing returning id into c;
  if c is null then raise exception 'ALREADY_EXISTS'; end if;
  return c;
end $$;

--
-- Name: add_handover_photos(text, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_handover_photos(p_id text, p_urls text[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not is_ops() then raise exception 'FORBIDDEN'; end if;
  if coalesce(array_length(p_urls,1),0) = 0 then return; end if;
  update bookings set handover_photos = handover_photos || p_urls,
    log = log || jsonb_build_array(jsonb_build_object('t', now(), 'm', 'Handover photo added (' || array_length(p_urls,1) || ')', 'by', staff_name()))
  where id = p_id;
  if not found then raise exception 'NOT_FOUND'; end if;
end $$;

--
-- Name: alteration_job_booking_active(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.alteration_job_booking_active() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare st text;
begin
  if new.source = 'booking' and new.status not in ('ready','cancelled') then
    select status into st from bookings where id = new.booking_id;
    if st is not null and st not in ('pending','confirmed') then raise exception 'BOOKING_NOT_ACTIVE'; end if;
  end if;
  return new;
end $$;

--
-- Name: apply_discount(text, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_discount(p_id text, p_amount integer, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare b bookings; begin
  if not is_owner() then raise exception 'FORBIDDEN'; end if;
  select * into b from bookings where id=p_id; if not found then raise exception 'NOT_FOUND'; end if;
  if b.status in ('cancelled','returned') then raise exception 'BAD_STATUS'; end if;
  if p_amount is null or p_amount <= 0 or p_amount > b.rent then raise exception 'BAD_AMOUNT'; end if;
  update bookings set rent = rent - p_amount, discount = discount + p_amount,
    log = log || jsonb_build_array(jsonb_build_object('t',now(),'m','Discount of Rs '||p_amount||' given'||case when length(trim(coalesce(p_reason,'')))>0 then ': '||trim(p_reason) else '' end,'by',staff_name()))
  where id=p_id;
end $$;

--
-- Name: approvals_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approvals_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if old.status <> 'pending' then raise exception 'APPROVAL_LOCKED'; end if;
  if new.booking_id is distinct from old.booking_id or new.action_type is distinct from old.action_type
     or new.request_details is distinct from old.request_details or new.requested_by is distinct from old.requested_by
     or new.requested_at is distinct from old.requested_at or new.shortfall is distinct from old.shortfall then
    raise exception 'APPROVAL_LOCKED';
  end if;
  if new.status <> 'pending' then
    if not is_owner() then raise exception 'FORBIDDEN'; end if;
    new.decided_by := coalesce(new.decided_by, auth.uid());
    new.decided_at := coalesce(new.decided_at, now());
    new.decided_by_name := staff_name();
  end if;
  return new;
end $$;

--
-- Name: approvals_stamp_request(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approvals_stamp_request() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.requested_by_name is null then new.requested_by_name := staff_name(); end if;
  return new;
end $$;

--
-- Name: blocks_before(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.blocks_before() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare b int; begin select buffer_days into b from settings;
  if exists(select 1 from bookings x where x.dress_id=new.dress_id and x.status<>'cancelled'
     and x.hold && daterange(new.start_date,new.end_date+1,'[)')) then raise exception 'BLOCK_CONFLICT'; end if;
  return new; end $$;

--
-- Name: booking_deposit(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.booking_deposit(p_rent integer) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select greatest(round(coalesce(p_rent,0) * s.advance_pct / 100.0)::int, s.advance_min) from settings s limit 1 $$;

--
-- Name: booking_start_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.booking_start_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.status in ('pending','confirmed') and (tg_op = 'INSERT' or new.start_date is distinct from old.start_date) and new.start_date < ist_today() then
    raise exception 'PAST_START';
  end if;
  return new;
end $$;

--
-- Name: bookings_before(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bookings_before() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare b int; chk boolean; paid_rent int; begin
  perform pg_advisory_xact_lock(hashtext(new.dress_id::text));
  select buffer_days into b from settings;
  new.hold := daterange(new.start_date, new.end_date + 1, '[)');
  if tg_op='INSERT' then chk := true;
  else chk := (new.start_date<>old.start_date or new.end_date<>old.end_date or new.dress_id<>old.dress_id or old.status='cancelled'); end if;
  if chk and new.status<>'cancelled' then
    if exists(select 1 from blocks k where k.dress_id=new.dress_id and daterange(k.start_date,k.end_date+1,'[)') && new.hold) then raise exception 'DATES_TAKEN'; end if;
    if exists(select 1 from dry_cleanings c where c.dress_id=new.dress_id and daterange(c.sent_on, dc_end(c)+1,'[)') && new.hold) then raise exception 'DATES_TAKEN'; end if;
    if exists(select 1 from bookings o where o.dress_id=new.dress_id and o.id<>new.id and o.status<>'cancelled' and o.hold && new.hold) then raise exception 'DATES_TAKEN'; end if;
    if not new.gap_override and exists(select 1 from bookings o where o.dress_id=new.dress_id and o.id<>new.id and o.status<>'cancelled'
       and daterange(o.start_date, o.end_date + b + 1, '[)') && daterange(new.start_date, new.end_date + b + 1, '[)')) then raise exception 'GAP_CLASH'; end if;
  end if;
  if new.status='out' then new.prep_status := 'delivered'; end if;
  if new.status in ('pending','confirmed') and new.prep_status='delivered' then raise exception 'BAD_PREP'; end if;
  -- Who did what: stamped by the database from the signed-in user, so it cannot be typed in or forged.
  if tg_op='INSERT' then
    if is_staff() then new.taken_by := auth.uid(); end if;                       -- online customer bookings stay empty
  else
    if new.prep_status='ready' and old.prep_status<>'ready' then new.prepared_by := auth.uid(); new.prepared_at := now(); end if;
    if old.prep_status='ready' and new.prep_status not in ('ready','delivered') then new.prepared_by := null; new.prepared_at := null; end if;
    if new.status='out' and old.status<>'out' then new.delivered_by := auth.uid(); end if;
    if new.status='returned' and old.status<>'returned' then new.returned_by := auth.uid(); end if;
  end if;
  -- The rental amount (plus any customization charge) must be received before a dress is handed over or marked returned.
  -- A shortfall needs the owner's approval. The owner may proceed without one.
  if tg_op='UPDATE' and old.status<>new.status and new.status in ('out','returned') then
    if not is_owner() then
      select coalesce(sum(amount) filter (where kind='rent'),0) - coalesce(sum(amount) filter (where kind='rent_refund'),0) into paid_rent from payments where booking_id=new.id;
      if paid_rent < new.rent + new.custom_charge and not exists(select 1 from approvals a where a.booking_id=new.id and a.status='approved' and a.shortfall >= new.rent + new.custom_charge - paid_rent) then raise exception 'SHORTFALL'; end if;
    end if;
  end if;
  if tg_op='UPDATE' then
    if not is_owner() and (new.rent<>old.rent or new.discount<>old.discount or new.deposit<>old.deposit) then raise exception 'OWNER_ONLY'; end if;
  end if;
  return new; end $$;

--
-- Name: bookings_link_customer(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bookings_link_customer() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare k text; c uuid;
begin
  if tg_op = 'INSERT' or new.phone is distinct from old.phone then
    if not phone_valid(new.phone) then raise exception 'BAD_PHONE'; end if;
  end if;
  if tg_op = 'INSERT' or new.phone is distinct from old.phone or new.customer_name is distinct from old.customer_name or new.customer_id is null then
    k := phone_key(new.phone);
    if length(trim(coalesce(new.customer_name, ''))) = 0 or length(k) = 0 then return new; end if;
    select id into c from customers where phone_key = k and lower(trim(name)) = lower(trim(new.customer_name));
    if c is null then
      insert into customers (name, phone_key, email) values (trim(new.customer_name), k, nullif(trim(coalesce(new.email, '')), ''))
        on conflict (phone_key, lower(trim(name))) do nothing;
      select id into c from customers where phone_key = k and lower(trim(name)) = lower(trim(new.customer_name));
    end if;
    new.customer_id := c;
  end if;
  return new;
end $$;

--
-- Name: bookings_per_month(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bookings_per_month(p_by text) RETURNS TABLE(month text, n integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select to_char(d, 'YYYY-MM'), count(*)::int
  from (select case when p_by = 'created' then (b.created_at at time zone 'Asia/Kolkata')::date else b.start_date end as d
        from bookings b where is_ops() and b.status <> 'cancelled') x
  where d >= (date_trunc('month', (now() at time zone 'Asia/Kolkata')::date) - interval '12 months')::date
  group by 1 order by 1 $$;

