CREATE FUNCTION public.cancel_booking(p_booking text, p_reason text, p_rent_refund integer, p_dep_refund integer, p_mode text, p_note text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
