begin
  return _cancel_booking_core(p_booking, p_reason, p_rent_refund, p_dep_refund, p_mode, p_note, null);
end $$;

--
-- Name: cash_book(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cash_book(p_day date) RETURNS TABLE(opening_known boolean, opening integer, cash_in integer, cash_refunds integer, expenses integer, expected integer, counted integer, difference integer, status text, note text, tallied_by uuid, tallied_at timestamp with time zone, anchor text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare a_day date; a_amt int; o_amt int; o_day date; s_day date; base int; mv int; ex int; ci int; cr int; ce int; op int; known boolean := true; anc text;
begin
  if not is_ops() then raise exception 'FORBIDDEN'; end if;
  if not is_owner() and p_day < date_trunc('month', ist_today())::date then raise exception 'FORBIDDEN'; end if;
  select t.day, t.counted into a_day, a_amt from cash_tally t where t.day < p_day order by t.day desc limit 1;
  if found then s_day := a_day + 1; base := a_amt; anc := 'counted cash of ' || a_day::text;
  else
    select s.cash_opening, s.cash_opening_date into o_amt, o_day from settings s;
    if o_amt is null or o_day is null or p_day < o_day then known := false;
    else s_day := o_day; base := o_amt; anc := 'opening cash set for ' || o_day::text; end if;
  end if;
  if known then
    select coalesce(sum(case when p.kind in ('rent','deposit') then p.amount else -p.amount end),0) into mv from payments p
      where p.kind in ('rent','deposit','deposit_refund','rent_refund') and p.mode ilike '%cash%' and ist_d(p.created_at) >= s_day and ist_d(p.created_at) < p_day;
    select coalesce(sum(x.amount),0) into ex from cash_expenses x where x.voided_at is null and x.mode ilike '%cash%' and x.spent_on >= s_day and x.spent_on < p_day;
    op := base + mv - ex;
  end if;
  select coalesce(sum(p.amount) filter (where p.kind in ('rent','deposit')),0), coalesce(sum(p.amount) filter (where p.kind in ('deposit_refund','rent_refund')),0) into ci, cr from payments p
    where p.kind in ('rent','deposit','deposit_refund','rent_refund') and p.mode ilike '%cash%' and ist_d(p.created_at) = p_day;
  select coalesce(sum(x.amount),0) into ce from cash_expenses x where x.voided_at is null and x.mode ilike '%cash%' and x.spent_on = p_day;
  return query select known, op, ci, cr, ce, case when known then op + ci - cr - ce end, t.counted, t.difference, t.status, t.note, t.tallied_by, t.tallied_at, anc
    from (select 1) one left join cash_tally t on t.day = p_day;
end $$;

--
-- Name: cash_liabilities(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cash_liabilities(p_day date) RETURNS TABLE(advance_pending integer, deposits_held integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare e timestamptz := ((p_day + 1)::text || ' 00:00:00+05:30')::timestamptz; a int; d int; begin
  if not is_ops() then raise exception 'FORBIDDEN'; end if;
  select coalesce(sum(greatest(0, x.adv - x.refunded)),0) into a from (
    select b.id,
      coalesce(sum(p.amount) filter (where p.purpose = 'advance' and p.created_at < e),0) adv,
      coalesce(sum(p.amount) filter (where p.kind = 'rent_refund' and p.created_at < e),0) refunded
    from bookings b left join payments p on p.booking_id = b.id
    where (b.picked_up_at is null or b.picked_up_at >= e)
      and coalesce((select max((l->>'t')::timestamptz) from jsonb_array_elements(b.log) l where l->>'m' = 'Cancelled'), 'infinity'::timestamptz) >= e
      and not (b.status = 'cancelled' and not exists(select 1 from jsonb_array_elements(b.log) l where l->>'m' = 'Cancelled'))
    group by b.id) x;
  select coalesce(sum(case p.kind when 'deposit' then p.amount when 'deposit_refund' then -p.amount when 'charge' then -p.amount else 0 end),0) into d from payments p where p.created_at < e;
  return query select a, d;
end $$;

--
-- Name: cash_position(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cash_position(p_day date) RETURNS TABLE(opening integer, cash_in integer, cash_out integer, expenses integer, expected integer, counted integer, note text, tallied_by uuid, tallied_at timestamp with time zone, anchor_day date)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare a_day date; a_amt int; mv int; ex int; i int; e int; o int; begin
  if not is_ops() then raise exception 'FORBIDDEN'; end if;
  if not is_owner() and p_day < date_trunc('month', ist_today())::date then raise exception 'FORBIDDEN'; end if;
  -- Start from the most recent tallied day before this one (or from the beginning if there is none).
  select t.day, t.counted into a_day, a_amt from cash_tally t where t.day < p_day order by t.day desc limit 1;
  a_amt := coalesce(a_amt, 0);
  select coalesce(sum(case when p.kind in ('rent','deposit') then p.amount else -p.amount end), 0) into mv from payments p
    where p.kind in ('rent','deposit','deposit_refund','rent_refund') and p.mode ilike '%cash%'
      and (p.created_at at time zone 'Asia/Kolkata')::date < p_day and (a_day is null or (p.created_at at time zone 'Asia/Kolkata')::date > a_day);
  select coalesce(sum(x.amount), 0) into ex from cash_expenses x where x.spent_on < p_day and (a_day is null or x.spent_on > a_day);
  o := a_amt + mv - ex;
  select coalesce(sum(p.amount) filter (where p.kind in ('rent','deposit')), 0), coalesce(sum(p.amount) filter (where p.kind in ('deposit_refund','rent_refund')), 0) into i, e from payments p
    where p.kind in ('rent','deposit','deposit_refund','rent_refund') and p.mode ilike '%cash%' and (p.created_at at time zone 'Asia/Kolkata')::date = p_day;
  select coalesce(sum(x.amount), 0) into ex from cash_expenses x where x.spent_on = p_day;
  return query select o, i, e, ex, o + i - e - ex, t.counted, t.note, t.tallied_by, t.tallied_at, a_day
    from (select 1) one left join cash_tally t on t.day = p_day;
end $$;

--
-- Name: cash_tally_day(date, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cash_tally_day(p_day date, p_counted integer, p_note text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not is_ops() then raise exception 'FORBIDDEN'; end if;
  if p_day is null or p_day > ist_today() then raise exception 'BAD_DATES'; end if;
  if not is_owner() and p_day < date_trunc('month', ist_today())::date then raise exception 'FORBIDDEN'; end if;
  if p_counted is null or p_counted < 0 then raise exception 'BAD_AMOUNT'; end if;
  insert into cash_tally(day, counted, note, tallied_by, tallied_at)
  values(p_day, p_counted, nullif(trim(coalesce(p_note,'')),''), auth.uid(), now())
  on conflict (day) do update set counted = excluded.counted, note = excluded.note, tallied_by = auth.uid(), tallied_at = now();
end $$;

--
-- Name: confirm_booking(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_booking(p_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare b bookings;
begin
  if not is_ops() then raise exception 'FORBIDDEN'; end if;
  select * into b from bookings where id = p_id for update;
  if not found then raise exception 'NOT_FOUND'; end if;
  if b.status <> 'pending' then raise exception 'BAD_STATUS'; end if;
  update bookings set status = 'confirmed',
    log = coalesce(log, '[]'::jsonb) || jsonb_build_array(jsonb_build_object('t', now(), 'm', 'Confirmed', 'by', staff_name()))
  where id = p_id;
end $$;

--
-- Name: ist_today(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ist_today() RETURNS date
    LANGUAGE sql STABLE
    AS $$ select (now() at time zone 'Asia/Kolkata')::date $$;

--
-- Name: decide_approval(uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.decide_approval(p_id uuid, p_approve boolean, p_note text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare a approvals; b bookings; amt int; md text; k_kind text; k_purpose text; deposit_total int;
begin
  if not is_owner() then raise exception 'FORBIDDEN'; end if;
  update approvals set status=case when p_approve then 'approved' else 'rejected' end,decided_by=auth.uid(),decided_at=now(),decision_note=nullif(trim(coalesce(p_note,'')),'')
  where id=p_id and status='pending' returning * into a;
  if not found then raise exception 'NOT_FOUND'; end if;
  select * into b from bookings where id=a.booking_id;
  select coalesce(sum(amount) filter(where kind='deposit'),0)-coalesce(sum(amount) filter(where kind in ('deposit_refund','charge')),0)
    into deposit_total from payments where booking_id=a.booking_id;
  if p_approve then
    if a.action_type='discount' then
      amt:=coalesce((a.request_details->>'amount')::int,0); if amt<=0 or amt>b.rent then raise exception 'BAD_AMOUNT'; end if;
      update bookings set rent=rent-amt,discount=discount+amt,log=log||jsonb_build_array(jsonb_build_object('t',now(),'m','Discount of Rs '||amt||' approved'||case when length(trim(coalesce(a.reason,'')))>0 then ': '||a.reason else '' end,'by',staff_name())) where id=a.booking_id;
    elsif a.action_type='booking_cancellation' then
      raise exception 'USE_DECIDE_CANCELLATION';
    elsif a.action_type='refund' then
      amt:=coalesce((a.request_details->>'amount')::int,0); k_kind:=coalesce(a.request_details->>'kind','rent_refund'); k_purpose:=coalesce(a.request_details->>'purpose','rent_refund'); md:=coalesce(a.request_details->>'mode','Cash');
      if amt<=0 then raise exception 'BAD_AMOUNT'; end if;
      insert into payments(booking_id,amount,kind,purpose,mode,remarks,approval_id) values(a.booking_id,amt,k_kind,k_purpose,md,coalesce(a.request_details->>'remarks','Owner-approved refund'),a.id);
    end if;
  end if;
  update bookings set log=log||jsonb_build_array(jsonb_build_object('t',now(),'m',case when p_approve then 'Approval: '||replace(a.action_type,'_',' ')||' approved' else 'Approval: '||replace(a.action_type,'_',' ')||' rejected' end||case when length(trim(coalesce(p_note,'')))>0 then ': '||trim(p_note) else '' end,'by',staff_name())) where id=a.booking_id;
end $$;

--
-- Name: decide_cancellation(uuid, integer, integer, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.decide_cancellation(p_approval uuid, p_rent_refund integer, p_dep_refund integer, p_mode text, p_note text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare a approvals; res jsonb;
begin
  if not is_owner() then raise exception 'FORBIDDEN'; end if;
  update approvals set status = 'approved', decided_by = auth.uid(), decided_at = now(), decision_note = nullif(trim(coalesce(p_note,'')),'')
    where id = p_approval and status = 'pending' and action_type = 'booking_cancellation' returning * into a;
  if not found then raise exception 'NOT_FOUND'; end if;
  res := _cancel_booking_core(a.booking_id, coalesce(nullif(trim(coalesce(a.reason,'')),''), 'Cancellation approved by owner'), p_rent_refund, p_dep_refund, p_mode, p_note, a.id);
  return res;
end $$;

--
-- Name: deliver_booking(text, integer, integer, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.deliver_booking(p_id text, p_deposit integer, p_rent integer, p_mode text, p_note text, p_idem text, p_shortfall_reason text, p_not_ready_note text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare b bookings; paid int; dep_held int; dep_pending int; owing int; r int; cl int; c int; o int; st text; msg text; nm text := staff_name();
begin
  if not is_ops() then raise exception 'FORBIDDEN'; end if;
  if length(coalesce(p_idem, '')) < 8 then raise exception 'BAD_REQUEST'; end if;
  insert into delivery_requests(idem, booking_id) values (p_idem, p_id) on conflict do nothing;
  if not found then return 'duplicate'; end if;
  select * into b from bookings where id = p_id for update;
  if not found then raise exception 'NOT_FOUND'; end if;
  if b.status not in ('pending', 'confirmed') then raise exception 'BAD_STATUS'; end if;

  select coalesce(sum(amount) filter (where kind in ('rent', 'charge')), 0) - coalesce(sum(amount) filter (where kind = 'rent_refund'), 0),
         coalesce(sum(amount) filter (where kind = 'deposit'), 0) - coalesce(sum(amount) filter (where kind in ('deposit_refund', 'charge')), 0)
    into paid, dep_held from payments where booking_id = p_id;
  dep_pending := greatest(0, b.deposit - dep_held); owing := greatest(0, b.rent + b.charges - paid);
  p_deposit := coalesce(p_deposit, 0); p_rent := coalesce(p_rent, 0);
  if dep_pending > 0 and p_deposit <> dep_pending then raise exception 'DEPOSIT_FULL_REQUIRED'; end if;
  if dep_pending = 0 then p_deposit := 0; end if;
  if p_rent < 0 or p_rent > owing then raise exception 'BAD_AMOUNT'; end if;
  if (p_deposit > 0 or p_rent > 0) and length(trim(coalesce(p_mode, ''))) = 0 then raise exception 'MODE_REQUIRED'; end if;

  if p_deposit > 0 then insert into payments(booking_id, amount, kind, purpose, mode) values (p_id, p_deposit, 'deposit', 'deposit', p_mode); end if;
  if p_rent > 0 then   -- rent first, then customization, then any other charge (same order the website used)
    r := least(p_rent, greatest(0, b.rent - paid)); cl := greatest(0, coalesce(b.custom_charge, 0) - greatest(0, paid - b.rent)); c := least(p_rent - r, cl); o := p_rent - r - c;
    if r > 0 then insert into payments(booking_id, amount, kind, purpose, mode) values (p_id, r, 'rent', 'rent', p_mode); end if;
    if c > 0 then insert into payments(booking_id, amount, kind, purpose, mode) values (p_id, c, 'rent', 'customization', p_mode); end if;
    if o > 0 then insert into payments(booking_id, amount, kind, purpose, mode) values (p_id, o, 'rent', 'other_charge', p_mode); end if;
  end if;

  -- Shortfall: the existing approval rule decides. If the owner has not approved it yet, the money stays recorded and delivery waits.
  begin
    st := request_shortfall(p_id, p_shortfall_reason);
  exception when others then
    if sqlerrm like '%NO_SHORTFALL%' then st := 'none'; else raise; end if;
  end;
  if st = 'pending' then return 'pending_approval'; end if;

  msg := 'Delivered' || case when p_deposit > 0 then '. Deposit Rs ' || p_deposit || ' collected (' || p_mode || ')' else '' end
      || case when p_rent > 0 then '. Rent Rs ' || p_rent || ' collected (' || p_mode || ')' else '' end
      || case when owing - p_rent > 0 then '. Shortfall of Rs ' || (owing - p_rent) || ' approved' else '' end
      || case when length(trim(coalesce(p_not_ready_note, ''))) > 0 then '. Delivered although not ready. Reason: ' || left(trim(p_not_ready_note), 600) else '' end;
  update bookings set status = 'out', picked_up_at = now(),
    log = coalesce(log, '[]'::jsonb) || jsonb_build_array(jsonb_build_object('t', now(), 'm', left(msg, 1500), 'by', nm))
  where id = p_id;           -- one-dress-out, deposit and shortfall rules fire here; any failure undoes the payments above too

  if length(trim(coalesce(p_not_ready_note, ''))) > 0 then   -- SA-3: tell the owner (information only)
    insert into owner_notices(kind, booking_id, message, created_by_name)
      values ('deliver_anyway', p_id, 'Delivered although not ready. ' || left(trim(p_not_ready_note), 600), nm);
  end if;
  return 'delivered';
end $$;

--
-- Name: dress_busy(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dress_busy(p_dress uuid) RETURNS TABLE(start_date date, hold_end date, end_date date)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select o.start_date, o.end_date + (select buffer_days from settings), o.end_date from bookings o
    where is_staff() and o.dress_id=p_dress and o.status<>'cancelled' and o.end_date + (select buffer_days from settings) >= current_date
  union all select k.start_date, k.end_date, k.end_date from blocks k where is_staff() and k.dress_id=p_dress and k.end_date>=current_date
  union all select c.sent_on, dc_end(c), dc_end(c) from dry_cleanings c where is_staff() and c.dress_id=p_dress and dc_end(c)>=current_date $$;

--
-- Name: dress_history(uuid, date, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dress_history(p_dress uuid, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_status text DEFAULT NULL::text) RETURNS TABLE(id text, customer_name text, created_at timestamp with time zone, start_date date, end_date date, returned_at timestamp with time zone, status text, original_price integer, discount integer, net_rent integer, charges integer, late_fee integer, damage_charge integer, paid integer, outstanding integer, return_notes text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not is_owner() then raise exception 'FORBIDDEN'; end if;
  return query select v.id,v.customer_name,v.created_at,v.start_date,v.end_date,v.returned_at,v.status,(v.rent+v.discount)::int,v.discount,v.rent,v.charges,v.late_fee,v.damage_charge,
      v.paid,(v.rent+v.charges-v.paid)::int,v.return_notes
    from booking_view v where v.dress_id=p_dress and (p_from is null or v.start_date>=p_from) and (p_to is null or v.start_date<=p_to)
      and (p_status is null or v.status=p_status) order by v.start_date desc;
end $$;

--
-- Name: dress_performance(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dress_performance(p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date) RETURNS TABLE(dress_id uuid, code text, name text, category text, colour_tags text[], image text, status text, acquired_on date, added_on date, completed integer, rental_days integer, gross integer, discounts integer, net_rent integer, avg_net integer, late_fees integer, damage_charges integer, other_charges integer, collected integer, first_booking date, last_booking date, washes integer, wash_cost integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not is_owner() then raise exception 'FORBIDDEN'; end if;
  return query
  select d.id,d.code,d.name,d.category,d.colour_tags,d.images[1],d.status,d.acquired_on,d.created_at::date,
    count(v.id)::int, coalesce(sum(v.end_date-v.start_date+1),0)::int,
    coalesce(sum(v.rent+v.discount),0)::int, coalesce(sum(v.discount),0)::int,
    coalesce(sum(v.rent - v.rent_refunded),0)::int,
    case when count(v.id)>0 then round(sum(v.rent - v.rent_refunded)::numeric/count(v.id))::int else 0 end,
    coalesce(sum(v.late_fee),0)::int, coalesce(sum(v.damage_charge),0)::int, coalesce(sum(greatest(0,v.charges-v.late_fee-v.damage_charge)),0)::int,
    coalesce(sum(v.paid),0)::int, min(v.start_date), max(v.start_date),
    (select count(*) from dry_cleanings c where c.dress_id=d.id and (p_from is null or c.sent_on>=p_from) and (p_to is null or c.sent_on<=p_to))::int,
    (select coalesce(sum(c.charge),0) from dry_cleanings c where c.dress_id=d.id and (p_from is null or c.sent_on>=p_from) and (p_to is null or c.sent_on<=p_to))::int
  from dresses d
  left join booking_view v on v.dress_id=d.id and v.status='returned'
       and (p_from is null or v.start_date>=p_from) and (p_to is null or v.start_date<=p_to)
  where d.status<>'archived'
  group by d.id;
end $$;

--
-- Name: dress_washes(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dress_washes(p_dress uuid, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date) RETURNS TABLE(id uuid, sent_on date, expected_back date, returned_on date, charge integer, notes text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not is_owner() then raise exception 'FORBIDDEN'; end if;
  return query select c.id,c.sent_on,c.expected_back,c.returned_on,c.charge,c.notes from dry_cleanings c
    where c.dress_id=p_dress and (p_from is null or c.sent_on>=p_from) and (p_to is null or c.sent_on<=p_to) order by c.sent_on desc;
end $$;

--
-- Name: dresses_unavailable(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dresses_unavailable(p_from date, p_to date) RETURNS SETOF uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select d.id from dresses d where is_staff() and (d.status<>'available'
  or exists(select 1 from bookings o where o.dress_id=d.id and o.status<>'cancelled'
      and daterange(o.start_date, o.end_date + (select buffer_days from settings) + 1,'[)') && daterange(p_from, p_to + (select buffer_days from settings) + 1,'[)'))
  or exists(select 1 from blocks k where k.dress_id=d.id and daterange(k.start_date,k.end_date+1,'[)') && daterange(p_from,p_to+1,'[)'))
  or exists(select 1 from dry_cleanings c where c.dress_id=d.id and daterange(c.sent_on, dc_end(c)+1,'[)') && daterange(p_from,p_to+1,'[)'))) $$;

--
-- Name: dry_cleanings_before(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dry_cleanings_before() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  perform pg_advisory_xact_lock(hashtext(new.dress_id::text));
  if new.returned_on is null then
    -- cannot be away while a customer has it or has it booked (a dress already returned does not count)
    if exists(select 1 from bookings b where b.dress_id=new.dress_id and b.status in ('pending','confirmed','out')
        and b.hold && daterange(new.sent_on, greatest(new.expected_back, ist_today())+1,'[)')) then raise exception 'CLEAN_CONFLICT'; end if;
    if exists(select 1 from dry_cleanings c where c.dress_id=new.dress_id and c.returned_on is null and c.id<>new.id) then raise exception 'ALREADY_CLEANING'; end if;
  end if;
  return new; end $$;

--
-- Name: enforce_one_out_per_dress(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_one_out_per_dress() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.status = 'out' and (tg_op = 'INSERT' or old.status is distinct from 'out') then
    perform pg_advisory_xact_lock(hashtext(new.dress_id::text));
    if exists (select 1 from bookings o where o.dress_id = new.dress_id and o.id <> new.id and o.status = 'out') then
      raise exception 'DRESS_ALREADY_OUT';
    end if;
  end if;
  return new;
end $$;

--
-- Name: enforce_owner_cancellation_approval(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_owner_cancellation_approval() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.status='cancelled' and old.status<>'cancelled' and not is_owner()
     and not exists(select 1 from approvals where booking_id=old.id and action_type='booking_cancellation' and status='approved') then
    raise exception 'OWNER_APPROVAL_REQUIRED';
  end if;
  return new;
end $$;

--
-- Name: enforce_owner_refund_approval(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_owner_refund_approval() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare b bookings; deposit_total int;
begin
  if is_owner() then return new; end if;
  select * into b from bookings where id=new.booking_id;
  select coalesce(sum(amount) filter(where kind='deposit'),0)-coalesce(sum(amount) filter(where kind in ('deposit_refund','charge')),0) into deposit_total from payments where booking_id=new.booking_id;
  if new.kind='rent_refund' and (new.approval_id is null or not exists(select 1 from approvals a where a.id=new.approval_id and a.booking_id=new.booking_id and a.status='approved' and (
      (a.action_type='refund' and a.request_details->>'kind'='rent_refund' and (a.request_details->>'amount')::int>=new.amount)
      or (a.action_type='booking_cancellation' and coalesce((a.request_details->>'refund_amount')::int,0)>=new.amount)))) then
    raise exception 'OWNER_APPROVAL_REQUIRED';
  end if;
  if new.kind='deposit_refund' then
    if new.amount>deposit_total then raise exception 'BAD_AMOUNT'; end if;
    if b.status='cancelled' and (new.approval_id is null or not exists(select 1 from approvals a where a.id=new.approval_id and a.booking_id=new.booking_id and a.action_type='booking_cancellation' and a.status='approved')) then
      raise exception 'OWNER_APPROVAL_REQUIRED';
    end if;
    if b.status not in ('cancelled','returned') then raise exception 'BAD_STATUS'; end if;
  end if;
  return new;
end $$;

--
-- Name: extend_rental(text, date, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.extend_rental(p_booking text, p_new_end date, p_charge integer, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare b bookings; why text := nullif(trim(coalesce(p_reason,'')),''); ch int := greatest(0, coalesce(p_charge,0)); extra int;
begin
  if not is_ops() then raise exception 'FORBIDDEN'; end if;
  if why is null then raise exception 'REASON_REQUIRED'; end if;
  select * into b from bookings where id = p_booking for update;
  if not found then raise exception 'NOT_FOUND'; end if;
  if b.status <> 'out' then raise exception 'BAD_STATUS'; end if;
  if p_new_end is null or p_new_end <= b.end_date then raise exception 'BAD_DATES'; end if;
  extra := p_new_end - b.end_date;
  update bookings set end_date = p_new_end, charges = charges + ch,
    log = log || jsonb_build_array(jsonb_build_object('t', now(),
      'm', 'Rental extended from ' || to_char(b.end_date,'DD Mon YYYY') || ' to ' || to_char(p_new_end,'DD Mon YYYY') || ' (' || extra || ' day' || case when extra = 1 then '' else 's' end || '). Extension charge Rs ' || ch || '. Reason: ' || why,
      'by', staff_name()))
  where id = p_booking;
  return jsonb_build_object('days', extra, 'charge', ch);
end $$;

--
-- Name: finish_dry_clean(uuid, date, integer, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finish_dry_clean(p_request uuid, p_date date, p_cost integer, p_notes text, p_result text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r dry_clean_requests; n text := nullif(trim(coalesce(p_notes,'')),''); cost int := greatest(0, coalesce(p_cost,0)); jobs int := 0;
begin
  if not is_ops() then raise exception 'FORBIDDEN'; end if;
  if p_result not in ('ok','reclean','damaged') then raise exception 'BAD_RESULT'; end if;
  if p_result <> 'ok' and n is null then raise exception 'NOTE_REQUIRED'; end if;
  select * into r from dry_clean_requests where id = p_request for update;
  if not found then raise exception 'NOT_FOUND'; end if;
  if r.status not in ('sent','returned_pending_check') then raise exception 'BAD_STATUS'; end if;
  if r.sent_on is not null and p_date < r.sent_on then raise exception 'BAD_DATES'; end if;

  if r.dry_cleaning_id is not null then
    update dry_cleanings set charge = cost, returned_on = p_date, notes = nullif(concat_ws(' · ', notes, n), '') where id = r.dry_cleaning_id;
  end if;

  if p_result = 'ok' then
    update dry_clean_requests set status = 'complete', returned_on = p_date, returned_by = auth.uid(), final_charge = cost, returned_condition = 'Ready',
      return_notes = n, completed_at = now(), completed_by = auth.uid() where id = r.id;
    update dresses set condition = coalesce(n, 'Ready after dry cleaning') where id = r.dress_id;
  elsif p_result = 'reclean' then
    -- Back in the queue, to be sent again. The round that just ended stays in the history with its cost.
    update dry_clean_requests set status = 'to_be_sent', dry_cleaning_id = null, sent_on = null, sent_by = null, expected_back = null, vendor = null,
      estimated_charge = 0, returned_on = null, final_charge = null, condition_notes = 'Not satisfactory, send to cleaner again: ' || n, added_at = now() where id = r.id;
    update dresses set condition = n where id = r.dress_id;
  else
    update dry_clean_requests set status = 'complete', returned_on = p_date, returned_by = auth.uid(), final_charge = cost, returned_condition = 'Damaged',
      return_notes = n, completed_at = now(), completed_by = auth.uid() where id = r.id;
    update dresses set status = 'maintenance', condition = n where id = r.dress_id;
    if r.booking_id is not null and not exists (select 1 from alteration_jobs j where j.booking_id = r.booking_id and j.source = 'damage' and j.status in ('pending_dispatch','at_unit','quality_check')) then
      insert into alteration_jobs(booking_id, dress_id, source, requirements, status) values (r.booking_id, r.dress_id, 'damage', 'Damaged at the cleaner: ' || n, 'pending_dispatch');
      jobs := 1;
    end if;
  end if;
  return jsonb_build_object('result', p_result, 'repair_job', jobs);
end $$;

--
-- Name: gap_override_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gap_override_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare aid uuid;
begin
  if not new.gap_override or auth.uid() is null or is_owner() then return new; end if;
  if tg_op = 'UPDATE' and old.gap_override and new.start_date = old.start_date and new.end_date = old.end_date and new.dress_id = old.dress_id then return new; end if;
  select a.id into aid from approvals a
   where a.action_type = 'gap_override' and a.status = 'approved' and a.requested_by = auth.uid() and a.decided_at > now() - interval '3 days'
     and a.request_details->>'dress_id' = new.dress_id::text and a.request_details->>'start' = new.start_date::text and a.request_details->>'end' = new.end_date::text
     and not exists (select 1 from gap_grant_uses u where u.approval_id = a.id)
   order by a.decided_at desc limit 1 for update;
  if aid is null then raise exception 'GAP_APPROVAL_REQUIRED'; end if;
  insert into gap_grant_uses(approval_id, used_for) values (aid, new.id);
  return new;
end $$;

