    LANGUAGE sql IMMUTABLE
    AS $$ select (ts at time zone 'Asia/Kolkata')::date $$;

--
-- Name: log_event(text, text, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_event(p_entity text, p_id text, p_dress uuid, p_booking text, p_action text, p_detail text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare nm text;
begin
  begin nm := staff_name(); exception when others then nm := null; end;
  insert into events(by_user, by_name, entity, entity_id, dress_id, booking_id, action, detail) values (auth.uid(), nm, p_entity, p_id, p_dress, p_booking, p_action, p_detail);
end $$;

--
-- Name: log_readiness(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_readiness(p_rows jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r jsonb; n int := 0; today date := (now() at time zone 'Asia/Kolkata')::date; b bookings; stg int; got int;
begin
  if not is_ops() then raise exception 'FORBIDDEN'; end if;
  if jsonb_typeof(p_rows) <> 'array' then return 0; end if;
  for r in select value from jsonb_array_elements(p_rows) limit 200 loop
    select * into b from bookings where id = r->>'booking_id' and status in ('pending', 'confirmed'); if not found then continue; end if;
    stg := b.start_date - today; if stg not between 0 and 2 or (r->>'stage') <> 'D-' || stg then continue; end if;
    insert into readiness_log (booking_id, dress_id, delivery_date, stage, ready, reason_codes, reasons)
      values (b.id, b.dress_id, b.start_date, 'D-' || stg, coalesce((r->>'ready')::boolean, false),
              coalesce((select array_agg(x) from jsonb_array_elements_text(coalesce(r->'reason_codes', '[]'::jsonb)) x), '{}'), left(r->>'reasons', 600))
      on conflict (booking_id, stage) do nothing;
    get diagnostics got = row_count; n := n + got;
  end loop;
  return n;
end $$;

--
-- Name: mark_delivered(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_delivered(p_id text, p_note text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare b bookings;
begin
  if not is_ops() then raise exception 'FORBIDDEN'; end if;
  select * into b from bookings where id = p_id for update;
  if not found then raise exception 'NOT_FOUND'; end if;
  if b.status not in ('pending', 'confirmed') then raise exception 'BAD_STATUS'; end if;
  update bookings set status = 'out', picked_up_at = now(),
    log = coalesce(log, '[]'::jsonb) || jsonb_build_array(jsonb_build_object('t', now(), 'm', left(coalesce(nullif(trim(p_note), ''), 'Delivered'), 1500), 'by', staff_name()))
  where id = p_id;                         -- the shortfall, one-dress-out and deposit rules fire here, exactly as before
end $$;

--
-- Name: merge_customers(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.merge_customers(p_from uuid, p_into uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare n int;
begin
  if not is_owner() then raise exception 'FORBIDDEN'; end if;
  if p_from = p_into or not exists (select 1 from customers where id = p_from) or not exists (select 1 from customers where id = p_into) then raise exception 'NOT_FOUND'; end if;
  update bookings set customer_id = p_into where customer_id = p_from;
  get diagnostics n = row_count;
  update customers t set email = coalesce(t.email, f.email) from customers f where t.id = p_into and f.id = p_from;
  delete from customers where id = p_from;
  return n;
end $$;

--
-- Name: notify_alteration_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_alteration_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare d dresses; begin
  select * into d from dresses where id=new.dress_id;
  if tg_op='INSERT' then
    insert into admin_notifications(target_role,kind,title,body,booking_id,created_by)
    values('staff','alteration','Alteration added',d.code||' is waiting to be sent to the tailoring unit.',new.booking_id,new.created_by);
  elsif new.status is distinct from old.status then
    insert into admin_notifications(target_role,kind,title,body,booking_id,created_by)
    values('all','alteration','Alteration status updated',d.code||' · '||replace(new.status,'_',' ')||'.',new.booking_id,auth.uid());
  end if;
  return new;
end $$;

--
-- Name: notify_cleaning_request(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_cleaning_request() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare d dresses; begin
  select * into d from dresses where id=new.dress_id;
  insert into admin_notifications(target_role,kind,title,body,booking_id,created_by)
  values('all','dry_cleaning','Dress added to Dry Cleaning List',d.code||' is waiting at the shop and has not been sent to the cleaner.',new.booking_id,new.added_by);
  return new;
end $$;

--
-- Name: notify_pending_approval(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_pending_approval() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.status='pending' then
    insert into admin_notifications(target_role,kind,title,body,booking_id,created_by)
    values('owner','approval',case new.action_type when 'shortfall' then 'Shortfall approval required' when 'discount' then 'Discount approval required' when 'refund' then 'Refund approval required' else 'Booking cancellation approval required' end,
      case new.action_type when 'shortfall' then 'Booking '||new.booking_id||' has a shortfall request of ₹'||coalesce(new.shortfall,0)||'.' else 'Booking '||new.booking_id||' · '||replace(new.action_type,'_',' ')||case when coalesce(new.request_details->>'amount','')<>'' then ': ₹'||(new.request_details->>'amount') else '' end||'.' end,
      new.booking_id,new.requested_by);
  end if;
  return new;
end $$;

--
-- Name: payments_purpose_default(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.payments_purpose_default() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.purpose is null then
    new.purpose := case new.kind when 'deposit' then 'deposit' when 'deposit_refund' then 'deposit_refund' when 'charge' then 'deposit_applied'
      when 'rent_refund' then 'rent_refund'
      else case when not exists(select 1 from payments x where x.booking_id=new.booking_id and x.kind='rent')
                 and now() < (select b.created_at from bookings b where b.id=new.booking_id) + interval '30 minutes' then 'advance' else 'rent' end end;
  end if;
  return new; end $$;

--
-- Name: payments_stamp(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.payments_stamp() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if auth.uid() is not null then new.created_by := auth.uid(); end if;   -- a signed-in user cannot record a payment in someone else's name
  new.created_at := now();                                               -- and cannot back-date it into a day that was already tallied
  return new;
end $$;

--
-- Name: phone_key(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.phone_key(p text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  select case
    when p ~ '^\s*\+' and regexp_replace(p, '\D', '', 'g') !~ '^91' then '+' || regexp_replace(p, '\D', '', 'g')
    else right(regexp_replace(coalesce(p, ''), '\D', '', 'g'), 10) end $$;

--
-- Name: phone_valid(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.phone_valid(p text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $_$
  select phone_key(p) ~ '^[6-9][0-9]{9}$' or phone_key(p) ~ '^\+[0-9]{8,15}$' $_$;

--
-- Name: prep_jobs(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prep_jobs() RETURNS TABLE(id uuid, booking_id text, dress_id uuid, dress_code text, dress_name text, image text, customer_name text, delivery_date date, status text, source text, requirements text, sent_on date, expected_return date, measurements_pending boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select j.id, j.booking_id, j.dress_id, d.code, d.name, d.images[1], b.customer_name, b.start_date,
         j.status, j.source, j.requirements, j.sent_on, j.expected_return, j.measurements_pending
  from alteration_jobs j join dresses d on d.id = j.dress_id left join bookings b on b.id = j.booking_id
  where is_staff() and j.status in ('pending_dispatch','at_unit','quality_check')
  order by coalesce(b.start_date, current_date), j.created_at $$;

--
-- Name: record_payment(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_payment(p_booking text, p_rows jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r jsonb; n int := 0; a int; k text;
begin
  if not is_ops() then raise exception 'FORBIDDEN'; end if;
  if not exists (select 1 from bookings where id = p_booking) then raise exception 'NOT_FOUND'; end if;
  if jsonb_typeof(p_rows) <> 'array' or jsonb_array_length(p_rows) = 0 then raise exception 'BAD_AMOUNT'; end if;
  for r in select value from jsonb_array_elements(p_rows) loop
    a := coalesce((r->>'amount')::int, 0); k := r->>'kind';
    if a <= 0 then raise exception 'BAD_AMOUNT'; end if;
    if k not in ('rent', 'deposit', 'rent_refund', 'deposit_refund', 'charge') then raise exception 'BAD_KIND'; end if;
    if length(trim(coalesce(r->>'mode', ''))) = 0 then raise exception 'MODE_REQUIRED'; end if;
    insert into payments(booking_id, amount, kind, purpose, mode, remarks, approval_id)
      values (p_booking, a, k, nullif(r->>'purpose', ''), r->>'mode', nullif(left(trim(coalesce(r->>'remarks', '')), 500), ''), nullif(r->>'approval_id', '')::uuid);
    n := n + 1;     -- the amount, refund-approval and who/when rules are triggers on payments and fire here
  end loop;
  return n;
end $$;

--
-- Name: record_wash_payment(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_wash_payment(p_wash uuid, p_mode text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare w dry_cleanings; d dresses; begin
  if not is_ops() then raise exception 'FORBIDDEN'; end if;
  if p_mode not in ('Cash','GPay / UPI','Card','Bank transfer') then raise exception 'BAD_MODE'; end if;
  select * into w from dry_cleanings where id = p_wash; if not found then raise exception 'NOT_FOUND'; end if;
  if w.charge <= 0 then raise exception 'BAD_AMOUNT'; end if;
  select * into d from dresses where id = w.dress_id;
  insert into cash_expenses(amount, category, mode, remarks, payee, dry_cleaning_id)
  values(w.charge, 'Dry Cleaning', p_mode, 'Dry cleaning ' || d.code || ' (sent ' || w.sent_on || ')', 'Dry cleaner', w.id);
exception when unique_violation then raise exception 'ALREADY_PAID'; end $$;

--
-- Name: request_action_approval(text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_action_approval(p_booking text, p_action text, p_details jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare b bookings; aid uuid; amount int; paid_total int; deposit_total int; rr int; dr int;
begin
  if not is_ops() or is_owner() then raise exception 'FORBIDDEN'; end if;
  if p_action not in ('discount','booking_cancellation','refund') then raise exception 'BAD_ACTION'; end if;
  select * into b from bookings where id=p_booking; if not found then raise exception 'NOT_FOUND'; end if;
  select coalesce(sum(amount) filter(where kind in ('rent','charge')),0)-coalesce(sum(amount) filter(where kind='rent_refund'),0),
         coalesce(sum(amount) filter(where kind='deposit'),0)-coalesce(sum(amount) filter(where kind in ('deposit_refund','charge')),0)
    into paid_total,deposit_total from payments where booking_id=p_booking;
  amount:=coalesce((p_details->>'amount')::int,0);
  rr:=coalesce((p_details->>'rent_refund')::int,(p_details->>'refund_amount')::int,0); dr:=coalesce((p_details->>'deposit_refund')::int,0);
  if p_action='discount' and (amount<=0 or amount>b.rent) then raise exception 'BAD_AMOUNT'; end if;
  if p_action='booking_cancellation' and (b.status not in ('pending','confirmed') or rr<0 or dr<0 or rr>greatest(0,paid_total) or dr>greatest(0,deposit_total)) then raise exception 'BAD_REQUEST'; end if;
  if p_action='booking_cancellation' and length(trim(coalesce(p_details->>'reason','')))=0 then raise exception 'REASON_REQUIRED'; end if;
  if p_action='refund' and amount<=0 then raise exception 'BAD_AMOUNT'; end if;
  if p_action='refund' and coalesce(p_details->>'kind','') not in ('deposit_refund','rent_refund') then raise exception 'BAD_REFUND_TYPE'; end if;
  if p_action='refund' and p_details->>'kind'='deposit_refund' and amount>deposit_total then raise exception 'BAD_AMOUNT'; end if;
  if p_action='refund' and p_details->>'kind'='rent_refund' and amount>paid_total then raise exception 'BAD_AMOUNT'; end if;
  if exists(select 1 from approvals where booking_id=p_booking and action_type=p_action and status='pending') then raise exception 'PENDING_EXISTS'; end if;
  insert into approvals(booking_id,shortfall,action_type,request_details,reason,status,requested_by)
  values(p_booking,null,p_action,coalesce(p_details,'{}'::jsonb),nullif(trim(coalesce(p_details->>'reason','')),''),'pending',auth.uid()) returning id into aid;
  return aid;
end $$;

--
-- Name: request_gap_override(uuid, date, date, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_gap_override(p_dress uuid, p_start date, p_end date, p_booking text, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare aid uuid;
begin
  if not is_ops() or is_owner() then raise exception 'FORBIDDEN'; end if;
  if p_dress is null or p_start is null or p_end is null or p_end < p_start then raise exception 'BAD_DATES'; end if;
  if length(trim(coalesce(p_reason, ''))) < 3 then raise exception 'REASON_REQUIRED'; end if;
  if exists (select 1 from approvals where action_type = 'gap_override' and status = 'pending' and requested_by = auth.uid()
             and request_details->>'dress_id' = p_dress::text and request_details->>'start' = p_start::text and request_details->>'end' = p_end::text) then raise exception 'PENDING_EXISTS'; end if;
  insert into approvals(booking_id, shortfall, action_type, request_details, reason, status, requested_by)
    values (nullif(p_booking, ''), null, 'gap_override', jsonb_build_object('dress_id', p_dress, 'dress_code', (select code from dresses where id = p_dress), 'dress_name', (select name from dresses where id = p_dress), 'start', p_start, 'end', p_end, 'reason', trim(p_reason)), trim(p_reason), 'pending', auth.uid())
    returning id into aid;
  return aid;
end $$;

--
-- Name: request_shortfall(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_shortfall(p_booking text, p_reason text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare b bookings; paid_rent int; short int; existing approvals; st text; begin
  if not is_ops() then raise exception 'FORBIDDEN'; end if;
  select * into b from bookings where id=p_booking; if not found then raise exception 'NOT_FOUND'; end if;
  select coalesce(sum(amount) filter (where kind='rent'),0) - coalesce(sum(amount) filter (where kind='rent_refund'),0) into paid_rent from payments where booking_id=p_booking;
  short := b.rent + b.custom_charge - paid_rent; if short <= 0 then raise exception 'NO_SHORTFALL'; end if;
  if not is_owner() and length(trim(coalesce(p_reason,'')))<3 then raise exception 'REASON_REQUIRED'; end if;
  select * into existing from approvals where booking_id=p_booking and status='approved' and shortfall>=short order by decided_at desc limit 1;
  if found then return 'approved'; end if;
  select * into existing from approvals where booking_id=p_booking and status='pending' limit 1;
  if found then return 'pending'; end if;
  st := case when is_owner() then 'approved' else 'pending' end;
  insert into approvals(booking_id,shortfall,reason,status,decided_by,decided_at) values(p_booking,short,nullif(trim(coalesce(p_reason,'')),''),st,case when is_owner() then auth.uid() end,case when is_owner() then now() end);
  update bookings set log = log || jsonb_build_array(jsonb_build_object('t',now(),'m',case when is_owner() then 'Shortfall of Rs '||short||' accepted by owner' else 'Approval requested: rental amount short by Rs '||short end,'by',staff_name())) where id=p_booking;
  return st; end $$;

--
-- Name: reschedule_booking(text, date, date, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reschedule_booking(p_id text, p_start date, p_end date, p_override boolean, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare b bookings; why text := trim(coalesce(p_reason, ''));
begin
  if not is_ops() then raise exception 'FORBIDDEN'; end if;
  if p_start is null or p_end is null or p_end < p_start then raise exception 'BAD_DATES'; end if;
  if length(why) < 3 then raise exception 'REASON_REQUIRED'; end if;
  select * into b from bookings where id = p_id for update;
  if not found then raise exception 'NOT_FOUND'; end if;
  if b.status not in ('pending', 'confirmed') then raise exception 'BAD_STATUS'; end if;
  update bookings set start_date = p_start, end_date = p_end, gap_override = coalesce(p_override, false),
    log = coalesce(log, '[]'::jsonb) || jsonb_build_array(jsonb_build_object('t', now(), 'by', staff_name(),
      'm', 'Rescheduled from ' || b.start_date || ' → ' || b.end_date || ' to ' || p_start || ' → ' || p_end
           || case when coalesce(p_override, false) then ' (cleaning gap override confirmed)' else '' end || '. Reason: ' || left(why, 500)))
  where id = p_id;                         -- double-booking, cleaning-gap and past-date rules fire here, exactly as before
end $$;

--
-- Name: return_booking(text, text, text, text[], boolean, integer, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.return_booking(p_booking text, p_condition text, p_notes text, p_photos text[], p_clean_required boolean, p_late_fee integer, p_damage_charge integer, p_refund_mode text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare c jsonb; res jsonb; sug int;
begin
  if not is_ops() then raise exception 'FORBIDDEN'; end if;
  c := _return_calc(p_booking, p_late_fee, p_damage_charge);
  res := return_dress(p_booking, p_condition, p_notes, p_photos, p_clean_required, greatest(0, coalesce(p_late_fee, 0)), greatest(0, coalesce(p_damage_charge, 0)),
                      (c->>'refund')::int, p_refund_mode, c->'applied');
  sug := (c->>'suggested_late_fee')::int;
  if greatest(0, coalesce(p_late_fee, 0)) <> sug then   -- a late fee different from the calculated one is allowed, but it is on record and the owner is told
    insert into owner_notices(kind, booking_id, message, created_by_name)
      values ('late_fee_changed', p_booking, 'Late fee charged Rs ' || greatest(0, coalesce(p_late_fee, 0)) || ' (calculated Rs ' || sug || ').', staff_name());
    update bookings set log = coalesce(log, '[]'::jsonb) || jsonb_build_array(jsonb_build_object('t', now(), 'by', staff_name(), 'm', 'Late fee set to Rs ' || greatest(0, coalesce(p_late_fee, 0)) || ' (calculated Rs ' || sug || ')')) where id = p_booking;
  end if;
  return res;
end $$;

--
-- Name: return_dress(text, text, text, text[], boolean, integer, integer, integer, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.return_dress(p_booking text, p_condition text, p_notes text, p_photos text[], p_clean_required boolean, p_late_fee integer, p_damage_charge integer, p_refund integer, p_refund_mode text, p_applied jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare b bookings; n text := nullif(trim(coalesce(p_notes,'')),''); cr boolean := coalesce(p_clean_required,false);
  lf int := greatest(0,coalesce(p_late_fee,0)); dc int := greatest(0,coalesce(p_damage_charge,0)); ref int := greatest(0,coalesce(p_refund,0));
  dep_held int; applied_total int := 0; a jsonb; ins_id uuid; already boolean := false; msg text;
begin
  if not is_ops() then raise exception 'FORBIDDEN'; end if;
  if p_condition not in ('good','minor_marks','needs_cleaning','damage_repair') then raise exception 'BAD_CONDITION'; end if;
  if (p_condition in ('good','damage_repair') and cr) or (p_condition = 'needs_cleaning' and not cr) then raise exception 'BAD_CLEANING_CHOICE'; end if;
  if p_condition = 'damage_repair' and (n is null or coalesce(array_length(p_photos,1),0) < 1) then raise exception 'DAMAGE_EVIDENCE'; end if;
  select * into b from bookings where id = p_booking for update;
  if not found then raise exception 'NOT_FOUND'; end if;
  if b.status <> 'out' then raise exception 'BAD_STATUS'; end if;

  select coalesce(sum(amount) filter (where kind='deposit'),0) - coalesce(sum(amount) filter (where kind in ('deposit_refund','charge')),0)
    into dep_held from payments where booking_id = p_booking;
  for a in select value from jsonb_array_elements(coalesce(p_applied,'[]'::jsonb)) loop
    if coalesce((a->>'amt')::int,0) <= 0 then raise exception 'BAD_AMOUNT'; end if;
    applied_total := applied_total + (a->>'amt')::int;
  end loop;
  if ref + applied_total > dep_held then raise exception 'BAD_AMOUNT'; end if;

  msg := 'Returned' || case when n is not null then ': '||n else '' end || '. Deposit handed back: Rs '||ref
    || case when applied_total > 0 then '. Deposit kept against dues: Rs '||applied_total else '' end
    || case when lf+dc > 0 then '. Charges: late fee Rs '||lf||', damage / repair Rs '||dc else '' end;

  update bookings set status = 'returned', returned_at = now(),
    charges = charges + lf + dc, late_fee = late_fee + lf, damage_charge = damage_charge + dc,
    return_notes = coalesce(n, return_notes),
    log = log || jsonb_build_array(jsonb_build_object('t', now(), 'm', msg, 'by', staff_name()))
  where id = p_booking;

  insert into return_inspections(booking_id, dress_id, condition, notes, photos, cleaning_required)
    values (p_booking, b.dress_id, p_condition, n, coalesce(p_photos,'{}'), cr) returning id into ins_id;

  if cr then
    select exists(select 1 from dry_clean_requests where dress_id = b.dress_id and status in ('to_be_sent','sent','returned_pending_check')) into already;
    if not already then
      insert into dry_clean_requests(dress_id, booking_id, inspection_id, condition, condition_notes, status)
        values (b.dress_id, p_booking, ins_id, p_condition, n, 'to_be_sent');
    end if;
  end if;

  if p_condition = 'damage_repair' then
    insert into alteration_jobs(booking_id, dress_id, inspection_id, source, requirements, status)
      values (p_booking, b.dress_id, ins_id, 'damage', coalesce(n,'Damage / repair required'), 'pending_dispatch');
    update dresses set status = 'maintenance', condition = coalesce(n,'Damage / repair required') where id = b.dress_id;
  elsif n is not null then
    update dresses set condition = n where id = b.dress_id;
  end if;

  if ref > 0 then
    insert into payments(booking_id, amount, kind, purpose, mode) values (p_booking, ref, 'deposit_refund', 'deposit_refund', coalesce(nullif(trim(p_refund_mode),''),'Cash'));
  end if;
  for a in select value from jsonb_array_elements(coalesce(p_applied,'[]'::jsonb)) loop
    insert into payments(booking_id, amount, kind, purpose, mode, remarks)
      values (p_booking, (a->>'amt')::int, 'charge', 'deposit_applied', 'From Security Deposit', nullif(a->>'why',''));
  end loop;

  return jsonb_build_object('inspection_id', ins_id, 'refund', ref, 'kept', applied_total, 'already_in_cleaning', already);
end $$;

--
-- Name: return_preview(text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.return_preview(p_booking text, p_late_fee integer, p_damage_charge integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not is_ops() then raise exception 'FORBIDDEN'; end if;
  return _return_calc(p_booking, p_late_fee, p_damage_charge);
end $$;

--
-- Name: revenue_report(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revenue_report(p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date) RETURNS TABLE(id text, dress_code text, dress_name text, category text, customer_name text, phone text, start_date date, end_date date, advance_received integer, rent_received integer, late_fee integer, damage_charge integer, status text, advance_refunded integer, net_amount integer, rental_amount integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not is_owner() then raise exception 'FORBIDDEN'; end if;
  return query
  select b.id,d.code,d.name,d.category,b.customer_name,b.phone,b.start_date,b.end_date,
    coalesce(x.adv,0)::int, (coalesce(x.rent_all,0)-coalesce(x.adv,0))::int, b.late_fee, b.damage_charge, b.status, coalesce(x.refunded,0)::int,
    (coalesce(x.rent_all,0) + b.late_fee + b.damage_charge - coalesce(x.refunded,0))::int, b.rent
  from bookings b join dresses d on d.id=b.dress_id
  left join lateral (select (array_agg(p.amount order by p.created_at, p.id) filter (where p.kind='rent'))[1] as adv,
      coalesce(sum(p.amount) filter (where p.kind='rent'),0) as rent_all, coalesce(sum(p.amount) filter (where p.kind='rent_refund'),0) as refunded
      from payments p where p.booking_id=b.id) x on true
  where b.status<>'pending' and (p_from is null or b.start_date>=p_from) and (p_to is null or b.start_date<=p_to)
  order by b.start_date, b.id;
end $$;

