--
-- Name: set_cash_opening(integer, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_cash_opening(p_amount integer, p_date date) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not is_owner() then raise exception 'FORBIDDEN'; end if;
  if p_amount is null or p_amount < 0 or p_date is null or p_date > ist_today() then raise exception 'BAD_AMOUNT'; end if;
  if exists(select 1 from cash_tally where day >= p_date) then raise exception 'ALREADY_TALLIED'; end if;       -- an opening cannot be moved past a tallied day
  update settings set cash_opening = p_amount, cash_opening_date = p_date where id = 1;
  insert into cash_audit(action, day, detail) values('opening_set', p_date, jsonb_build_object('amount', p_amount));
end $$;

--
-- Name: set_custom_charge(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_custom_charge(p_id text, p_amount integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare b bookings; begin
  if not is_ops() then raise exception 'FORBIDDEN'; end if;
  select * into b from bookings where id=p_id; if not found then raise exception 'NOT_FOUND'; end if;
  if b.status not in ('pending','confirmed','out') then raise exception 'BAD_STATUS'; end if;
  if p_amount is null or p_amount < 0 then raise exception 'BAD_AMOUNT'; end if;
  update bookings set charges = charges - custom_charge + p_amount, custom_charge = p_amount,
    log = log || jsonb_build_array(jsonb_build_object('t',now(),'m','Customization charge set to Rs '||p_amount,'by',staff_name()))
  where id=p_id;
end $$;

--
-- Name: set_delivery_details(text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_delivery_details(p_id text, p_mode text, p_address text, p_slot text, p_assignee text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare m text := nullif(trim(coalesce(p_mode,'')),'');
begin
  if not is_ops() then raise exception 'FORBIDDEN'; end if;
  if m is not null and m not in ('pickup','courier') then raise exception 'BAD_MODE'; end if;
  update bookings set delivery_mode = m, delivery_address = nullif(trim(coalesce(p_address,'')),''),
    delivery_slot = nullif(trim(coalesce(p_slot,'')),''), delivery_assignee = nullif(trim(coalesce(p_assignee,'')),''),
    log = log || jsonb_build_array(jsonb_build_object('t', now(), 'm', 'Delivery details updated', 'by', staff_name()))
  where id = p_id;
  if not found then raise exception 'NOT_FOUND'; end if;
end $$;

