--
-- Name: set_packed(text, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_packed(p_id text, p_done boolean, p_note text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare b bookings;
begin
  if not is_ops() then raise exception 'FORBIDDEN'; end if;
  select * into b from bookings where id = p_id for update;
  if not found then raise exception 'NOT_FOUND'; end if;
  if b.status not in ('pending', 'confirmed') then raise exception 'BAD_STATUS'; end if;
  update bookings set packed_at = case when p_done then now() else null end, packed_by = case when p_done then auth.uid() else null end,
    log = coalesce(log, '[]'::jsonb) || jsonb_build_array(jsonb_build_object('t', now(), 'by', staff_name(),
      'm', case when p_done then 'Packed and checked' || coalesce('. ' || nullif(left(trim(p_note), 300), ''), '') else 'Packed mark removed' end))
  where id = p_id;
end $$;

--
-- Name: staff_bookings_per_month(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_bookings_per_month() RETURNS TABLE(month text, taken_by uuid, n integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select to_char((b.created_at at time zone 'Asia/Kolkata')::date, 'YYYY-MM'), b.taken_by, count(*)::int
  from bookings b
  where is_ops() and b.status <> 'cancelled' and b.taken_by is not null
    and (b.created_at at time zone 'Asia/Kolkata')::date >= (date_trunc('month', (now() at time zone 'Asia/Kolkata')::date) - interval '12 months')::date
  group by 1, 2 $$;

--
-- Name: staff_create_booking(uuid, date, date, text, text, text, text, integer, text, integer, boolean, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_create_booking(p_dress uuid, p_start date, p_end date, p_name text, p_phone text, p_email text, p_notes text, p_advance integer, p_mode text, p_discount integer, p_override boolean, p_custom integer DEFAULT 0) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare d dresses; n int; v_id text; v_rent int; begin
  if not is_ops() then raise exception 'FORBIDDEN'; end if;
  if coalesce(p_discount,0)>0 and not is_owner() then raise exception 'OWNER_ONLY'; end if;
  if p_end<p_start or p_end-p_start>30 then raise exception 'BAD_DATES'; end if;
  if length(trim(coalesce(p_name,'')))<2 or regexp_replace(coalesce(p_phone,''),'\D','','g') !~ '^\d{10,13}$' then raise exception 'BAD_CONTACT'; end if;
  select * into d from dresses where id=p_dress and status='available';
  if not found then raise exception 'NOT_AVAILABLE'; end if;
  n := p_end-p_start+1;
  v_rent := greatest(0, d.price + greatest(0,n-d.included_days)*d.extra_day_fee - coalesce(p_discount,0));
  insert into bookings(dress_id,customer_name,phone,email,alteration_notes,start_date,end_date,rent,discount,deposit,custom_charge,charges,status,gap_override,log)
  values(p_dress,trim(p_name),p_phone,p_email,nullif(trim(coalesce(p_notes,'')),''),p_start,p_end,v_rent,coalesce(p_discount,0),booking_deposit(v_rent),greatest(0,coalesce(p_custom,0)),greatest(0,coalesce(p_custom,0)),'confirmed',coalesce(p_override,false),
    jsonb_build_array(jsonb_build_object('t',now(),'m',case when coalesce(p_override,false) then 'Created by staff. Cleaning gap override: availability checked and confirmed' else 'Created by staff' end)))
  returning id into v_id;
  -- p_advance is the part of the money received that counts as rent. The refundable deposit is recorded separately by the website.
  if coalesce(p_advance,0)>0 then insert into payments(booking_id,amount,kind,mode) values(v_id,p_advance,'rent',p_mode); end if;
  update dresses set popularity=popularity+1 where id=p_dress;
  return v_id;
exception when exclusion_violation then raise exception 'DATES_TAKEN'; end $_$;

--
-- Name: staff_create_booking_full(uuid, date, date, text, text, text, text, integer, text, integer, boolean, integer, integer, text, integer, date, text, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_create_booking_full(p_dress uuid, p_start date, p_end date, p_name text, p_phone text, p_email text, p_alt_notes text, p_advance integer, p_mode text, p_discount integer, p_override boolean, p_custom integer, p_deposit integer, p_deposit_ref text, p_cust_paid integer, p_event_date date, p_event_type text, p_notes text, p_alt jsonb, p_delivery jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_id text; j uuid; dm text := nullif(trim(coalesce(p_delivery->>'mode','')),'');
begin
  if not is_ops() then raise exception 'FORBIDDEN'; end if;
  v_id := staff_create_booking(p_dress, p_start, p_end, p_name, p_phone, p_email, p_alt_notes, p_advance, p_mode, p_discount, p_override, p_custom);
  if coalesce(p_deposit,0) > 0 then
    insert into payments(booking_id, amount, kind, purpose, mode, remarks) values (v_id, p_deposit, 'deposit', 'deposit', p_mode, nullif(trim(coalesce(p_deposit_ref,'')),''));
  end if;
  if coalesce(p_cust_paid,0) > 0 then
    insert into payments(booking_id, amount, kind, purpose, mode) values (v_id, p_cust_paid, 'rent', 'customization', p_mode);
  end if;
  perform set_booking_details(v_id, p_event_date, p_event_type, p_notes);
  if p_delivery is not null then
    if dm is not null and dm not in ('pickup','courier') then raise exception 'BAD_MODE'; end if;
    update bookings set delivery_mode = dm, delivery_address = nullif(trim(coalesce(p_delivery->>'address','')),''),
      delivery_slot = nullif(trim(coalesce(p_delivery->>'slot','')),''), delivery_assignee = nullif(trim(coalesce(p_delivery->>'assignee','')),'')
    where id = v_id;
  end if;
  if p_alt is not null then
    select id into j from alteration_jobs where booking_id = v_id and status <> 'cancelled' limit 1;
    if found then
      update alteration_jobs set checklist = coalesce(p_alt->'checklist','[]'::jsonb), measurements = coalesce(p_alt->'measurements','{}'::jsonb),
        measurements_pending = coalesce((p_alt->>'measurements_pending')::boolean,false), updated_at = now() where id = j;
    else
      insert into alteration_jobs(booking_id, dress_id, status, requirements, checklist, measurements, measurements_pending)
        values (v_id, p_dress, 'pending_dispatch', coalesce(nullif(trim(coalesce(p_alt->>'requirements','')),''), p_alt_notes, 'Alterations needed'),
          coalesce(p_alt->'checklist','[]'::jsonb), coalesce(p_alt->'measurements','{}'::jsonb), coalesce((p_alt->>'measurements_pending')::boolean,false));
    end if;
  end if;
  return v_id;
end $$;

--
-- Name: staff_name(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_name() RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ select coalesce(nullif(s.name,''), u.email, 'staff') from staff s left join auth.users u on u.id=s.user_id where s.user_id=auth.uid() $$;

--
-- Name: sync_alteration_job(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_alteration_job() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare txt text := nullif(trim(coalesce(new.alteration_notes,'')),''); j alteration_jobs%rowtype;
begin
  select * into j from alteration_jobs where booking_id=new.id and source='booking' and status not in ('ready','cancelled') limit 1;
  if new.status='cancelled' then
    if found then update alteration_jobs set status='cancelled', updated_at=now() where id=j.id; end if;
    return new;
  end if;
  if txt is null then
    if found and j.status='pending_dispatch' then update alteration_jobs set status='cancelled', updated_at=now() where id=j.id; end if;
    return new;
  end if;
  if found then
    if j.requirements is distinct from txt then update alteration_jobs set requirements=txt, updated_at=now() where id=j.id; end if;
  elsif new.status in ('pending','confirmed')
        and not exists (select 1 from alteration_jobs d where d.booking_id=new.id and d.source='booking' and d.status='ready') then
    insert into alteration_jobs(booking_id,dress_id,status,requirements,created_by)
    values (new.id,new.dress_id,'pending_dispatch',txt,new.taken_by);
  end if;
  return new;
end $$;

--
-- Name: tally_cash(date, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tally_cash(p_day date, p_counted integer, p_note text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare cb record; diff int; had boolean; begin
  if not is_ops() then raise exception 'FORBIDDEN'; end if;
  if p_day is null or p_day > ist_today() then raise exception 'BAD_DATES'; end if;
  if not is_owner() and p_day < date_trunc('month', ist_today())::date then raise exception 'FORBIDDEN'; end if;
  if p_counted is null or p_counted < 0 then raise exception 'BAD_AMOUNT'; end if;
  select * into cb from cash_book(p_day);
  if not cb.opening_known then raise exception 'OPENING_REQUIRED'; end if;
  diff := p_counted - cb.expected;
  if diff <> 0 and length(trim(coalesce(p_note,''))) < 3 then raise exception 'REMARK_REQUIRED'; end if;
  select exists(select 1 from cash_tally where day = p_day) into had;
  if had and not is_owner() then raise exception 'ALREADY_TALLIED'; end if;           -- only the owner may change a day that was already tallied
  insert into cash_tally(day, counted, expected, difference, status, note, tallied_by, tallied_at)
  values(p_day, p_counted, cb.expected, diff, case when diff = 0 then 'reconciled' else 'discrepancy' end, nullif(trim(coalesce(p_note,'')),''), auth.uid(), now())
  on conflict (day) do update set counted = excluded.counted, expected = excluded.expected, difference = excluded.difference, status = excluded.status,
    note = excluded.note, tallied_by = auth.uid(), tallied_at = now();
  insert into cash_audit(action, day, detail) values(case when had then 'tally_changed' else 'tally' end, p_day, jsonb_build_object('expected', cb.expected, 'counted', p_counted, 'difference', diff, 'note', p_note));
end $$;

--
-- Name: touch_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.touch_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin new.updated_at := now(); return new; end $$;

--
-- Name: trg_alteration_events(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_alteration_events() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare kind text := case when new.source = 'damage' then 'Repair' else 'Alteration' end;
begin
  if tg_op = 'INSERT' then perform log_event('alteration', new.id::text, new.dress_id, new.booking_id, kind || ' added', left(new.requirements, 200));
  elsif new.status is distinct from old.status then perform log_event('alteration', new.id::text, new.dress_id, new.booking_id, kind || ' status changed', old.status || ' → ' || new.status || coalesce(' · ' || nullif(left(new.notes, 200), ''), ''));
  end if;
  return new;
end $$;

--
-- Name: trg_cleaning_events(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_cleaning_events() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if tg_op = 'INSERT' then perform log_event('cleaning', new.id::text, new.dress_id, new.booking_id, 'Added to cleaning list', left(new.condition_notes, 200));
  elsif new.status is distinct from old.status then perform log_event('cleaning', new.id::text, new.dress_id, new.booking_id, 'Cleaning status changed', old.status || ' → ' || new.status || coalesce(' · ' || nullif(left(coalesce(new.return_notes, new.condition_notes), 200), ''), ''));
  end if;
  return new;
end $$;

--
-- Name: trg_dress_events(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_dress_events() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.status is distinct from old.status then perform log_event('dress', new.id::text, new.id, null, 'Status changed', old.status || ' → ' || new.status); end if;
  if new.location is distinct from old.location then perform log_event('dress', new.id::text, new.id, null, 'Store location changed', coalesce(old.location,'none') || ' → ' || coalesce(new.location,'none')); end if;
  return new;
end $$;

--
-- Name: void_expense(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.void_expense(p_id bigint, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare x cash_expenses; begin
  if not is_owner() then raise exception 'FORBIDDEN'; end if;
  if length(trim(coalesce(p_reason,''))) < 3 then raise exception 'REMARK_REQUIRED'; end if;
  update cash_expenses set voided_at = now(), voided_by = auth.uid(), void_reason = trim(p_reason) where id = p_id and voided_at is null returning * into x;
  if not found then raise exception 'NOT_FOUND'; end if;
  insert into cash_audit(action, day, detail) values('expense_voided', x.spent_on, jsonb_build_object('id', x.id, 'amount', x.amount, 'category', x.category, 'reason', p_reason));
end $$;

