--
-- Name: booking_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.booking_view WITH (security_invoker='true') AS
 SELECT b.id,
    b.dress_id,
    b.customer_name,
    b.phone,
    b.email,
    b.notes,
    b.start_date,
    b.end_date,
    b.rent,
    b.discount,
    b.charges,
    b.deposit,
    b.status,
    b.gap_override,
    b.hold,
    b.picked_up_at,
    b.returned_at,
    b.log,
    b.created_at,
    b.alteration_notes,
    b.alteration_updated_at,
    b.alteration_updated_by,
    b.prep_status,
    b.late_fee,
    b.damage_charge,
    b.return_notes,
    b.taken_by,
    b.prepared_by,
    b.prepared_at,
    b.delivered_by,
    b.returned_by,
    b.custom_charge,
    d.code AS dress_code,
    d.name AS dress_name,
    d.category,
    ((COALESCE(rp.rent_in, (0)::bigint) - COALESCE(rp.rent_out, (0)::bigint)))::integer AS paid,
    ((COALESCE(rp.dep_in, (0)::bigint) - COALESCE(rp.dep_out, (0)::bigint)))::integer AS deposit_held,
    (COALESCE(rp.rent_out, (0)::bigint))::integer AS rent_refunded,
    b.booking_date,
    b.event_type,
    b.event_date,
    b.delivery_mode,
    b.delivery_address,
    b.delivery_slot,
    b.delivery_assignee,
    b.packed_at,
    b.packed_by,
    b.customer_id
   FROM ((public.bookings b
     JOIN public.dresses d ON ((d.id = b.dress_id)))
     LEFT JOIN LATERAL ( SELECT sum(p.amount) FILTER (WHERE (p.kind = ANY (ARRAY['rent'::text, 'charge'::text]))) AS rent_in,
            sum(p.amount) FILTER (WHERE (p.kind = 'rent_refund'::text)) AS rent_out,
            sum(p.amount) FILTER (WHERE (p.kind = 'deposit'::text)) AS dep_in,
            sum(p.amount) FILTER (WHERE (p.kind = ANY (ARRAY['deposit_refund'::text, 'charge'::text]))) AS dep_out
           FROM public.payments p
          WHERE (p.booking_id = b.id)) rp ON (true));

